package io.lumine.mythic.lib.script.condition;import io.lumine.mythic.lib.skill.SkillMetadata;import io.lumine.mythic.lib.util.configobject.EmptyConfigObject;import vn.svframe.mythiclibfabric.MythicLibFabricMod;import java.util.Map;public class RawCondition extends Condition{private final String raw;public RawCondition(String raw){super(new EmptyConfigObject());this.raw=raw;}public boolean isMet(SkillMetadata metadata){return MythicLibFabricMod.castInline(Map.of("conditions",java.util.List.of(raw),"mechanics",java.util.List.of()),io.lumine.mythic.lib.skill.SkillMetadataContextBridge.context(metadata));}}